ALTER TABLE public.company_info ADD COLUMN IF NOT EXISTS company_template_sharing_version integer DEFAULT 0 NOT NULL;
WITH canonical AS (SELECT * FROM public.company_customization WHERE BTRIM(COALESCE(badge_template_layout_data,''))<>'' ORDER BY updated_at DESC NULLS LAST,location_id LIMIT 1)
UPDATE public.company_customization target SET badge_template_company_name=canonical.badge_template_company_name,badge_template_logo_url=canonical.badge_template_logo_url,badge_template_quote=canonical.badge_template_quote,badge_template_signatory_name=canonical.badge_template_signatory_name,badge_template_signatory_title=canonical.badge_template_signatory_title,badge_template_back_instructions=canonical.badge_template_back_instructions,badge_template_show_quote=canonical.badge_template_show_quote,badge_template_show_employee_id=canonical.badge_template_show_employee_id,badge_template_show_issue_date=canonical.badge_template_show_issue_date,badge_template_show_barcode=canonical.badge_template_show_barcode,badge_template_show_badge_text=canonical.badge_template_show_badge_text,badge_template_magstripe_enabled=canonical.badge_template_magstripe_enabled,badge_template_magstripe_track1=canonical.badge_template_magstripe_track1,badge_template_magstripe_track2=canonical.badge_template_magstripe_track2,badge_template_magstripe_track3=canonical.badge_template_magstripe_track3,badge_template_magstripe_command=canonical.badge_template_magstripe_command,badge_template_nfc_enabled=canonical.badge_template_nfc_enabled,badge_template_nfc_payload=canonical.badge_template_nfc_payload,badge_template_nfc_writer_command=canonical.badge_template_nfc_writer_command,badge_template_nfc_verify_command=canonical.badge_template_nfc_verify_command,badge_template_layout_data=canonical.badge_template_layout_data FROM canonical;
WITH canonical AS (SELECT customer_card_template_layout_data FROM public.company_customization WHERE BTRIM(COALESCE(customer_card_template_layout_data,''))<>'' ORDER BY updated_at DESC NULLS LAST,location_id LIMIT 1)
UPDATE public.company_customization target SET customer_card_template_layout_data=canonical.customer_card_template_layout_data FROM canonical;
UPDATE public.company_info SET company_template_sharing_version=1 WHERE company_info_id=1;
